
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_zvpbeint_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_zvpbeint", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.030867132701338e-02, -6.927946883539710e-02, -6.780239364881760e-02, -6.568454558400660e-02, -6.265235030722133e-02, -5.832233121902847e-02, -5.217496802734885e-02, -4.358803202682753e-02, -3.220966466352784e-02, -1.974016198420325e-02, -1.625334408644585e-02, -4.229295447193780e-02, -4.807813871931682e-02, -3.572924598974001e-02, -2.166802636301226e-02, -1.306334115035053e-02, -1.459302353816165e-02, -8.241631848207979e-03, -2.295605187484643e-03, -4.421610925465529e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


